; =============================================================================
; Ganbare Goemon - expansion banks 0x10-0x1F (256 KiB ROM)
;
;   0x10      Chinese font loader / glyph expander (slot 0x8000)
;   0x11-0x12 Chinese glyph bitmaps (1bpp 12x12, 24 B/glyph)
;   0x13      unused glyph bank
;   0x14-0x17 shadow text banks generated by tools/build_texts.py
;   0x18      Game Over code + Chinese streams (slot 0x6000)
;   0x19-0x1F unused glyph banks
;
; Generated data (glyphs, shadows, Game Over streams) is produced by
; tools/bdf2asm.py and tools/build_texts.py.  All banks are PHASE'd at
; their runtime address; the ROM image itself is emitted sequentially.
; =============================================================================

	PHASE	08000h			; bank 0x10 (code, slot 0x8000)
	include	"logic/zh_font_loader.asm"
	; pad to 8KB
	DS	0x2000 - ($ & 0x1FFF), 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x11 (glyph data)
	include	"gfx/zh_glyphs_bank11.asm"
	UNPHASE

	PHASE	08000h			; bank 0x12 (glyph data)
	include	"gfx/zh_glyphs_bank12.asm"
	UNPHASE

	PHASE	08000h			; bank 0x13 (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x14 (shadow of bank 1)
	IFDEF	ZH_SHADOW
	INCBIN	"work/bank14.bin"
	ELSE
	DS	0x2000, 0xFF
	ENDIF
	ASSERT	$ == 0xA000
	UNPHASE

	PHASE	08000h			; bank 0x15 (shadow of bank C)
	IFDEF	ZH_SHADOW
	INCBIN	"work/bank15.bin"
	ELSE
	DS	0x2000, 0xFF
	ENDIF
	ASSERT	$ == 0xA000
	UNPHASE

	PHASE	08000h			; bank 0x16 (shadow of bank 2)
	IFDEF	ZH_SHADOW
	INCBIN	"work/bank16.bin"
	ELSE
	DS	0x2000, 0xFF
	ENDIF
	ASSERT	$ == 0xA000
	UNPHASE

	PHASE	08000h			; bank 0x17 (shadow of bank F)
	IFDEF	ZH_SHADOW
	INCBIN	"work/bank17.bin"
	ELSE
	DS	0x2000, 0xFF
	ENDIF
	ASSERT	$ == 0xA000
	UNPHASE

	PHASE	06000h			; bank 0x18 (Game Over code + streams)
	include	"logic/zh_gameover.asm"
	UNPHASE

	PHASE	08000h			; bank 0x19 (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1A (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1B (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1C (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1D (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1E (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE

	PHASE	08000h			; bank 0x1F (unused glyph bank)
	DS	0x2000, 0xFF
	UNPHASE
